"""Offline generator for the cinbase Stroke table (筆畫表).

Reads the named CNS11643 全字庫 open-data files and writes the .cin source of
the Stroke table used by the 筆畫輸入法 (PIME) Service::

    python cnsstroke2cin.py CNS_strokes_sequence.txt <mapping dir|files...> \\
        -o ../cin/CnsStroke.cin --release 20260805

Inputs (release index https://data.cns11643.gov.tw/opendata/release.txt):

* ``CNS_strokes_sequence.txt`` -- ``CNS字碼 <TAB> 筆順``, digits ``1..5`` =
  橫豎撇點折 (see 全字庫屬性資料說明文件.txt in the same zip).
* ``CNS2UNICODE_Unicode*.txt`` -- ``CNS字碼 <TAB> Unicode碼位(16進位)``, from
  the release's MapingTables.zip; several files, one per plane group.

The digit codes are mapped onto the Five-stroke keyset (五筆畫) ``h s p n z``
displayed as ``一丨丿丶乙``.  The output is an ordinary CMIME table, so the
standard converter takes over from here::

    python cintojson.py CnsStroke.cin

The same run also writes ``json/<stem>.LICENSE.txt``, the licence notice that
ships beside the runtime JSON.  The installer copies ``json/`` and excludes
``cin/``, and the converter's own ``saveList`` leaves no licence key in the
JSON, so the OGDL-1.0 顯名聲明 needs a file of its own where the data actually
reaches users::

    python cnsstroke2cin.py CNS_strokes_sequence.txt <MapingTables 目錄> \\
        -o ../cin/CnsStroke.cin --release 20260805 --emit-license

``--emit-license`` writes only that notice and exits.  The exhibit text depends
on nothing but the constants below and ``--release``, so the CNS raw inputs are
not needed to reproduce the committed notice — which is the point: a notice
nobody can regenerate is a hand-written copy waiting to drift.

Deterministic: the same inputs always produce byte-identical output.
"""

import argparse
import glob
import importlib.util
import os
import sys

# CNS digit -> Five-stroke key, per 全字庫屬性資料說明文件.txt (1 橫 2 豎 3 撇 4 點 5 折)
# folded onto the five keys documented in GLOSSARY.md.
STROKE_KEY_BY_DIGIT = {
    "1": "h",  # 橫
    "2": "s",  # 豎
    "3": "p",  # 撇
    "4": "n",  # 點/捺
    "5": "z",  # 折
}

ROOT_GLYPH_BY_KEY = {
    "h": "一",
    "s": "丨",
    "p": "丿",
    "n": "丶",
    "z": "乙",
}

# The Service declares maxCharLength 30 and cinbase never extends a composition
# past it (see cinbase/__init__.py), so a longer code can never be typed; CNS
# carries sequences up to 64 strokes and those characters stay out (ADR 0002) --
# eight the closure tiers would otherwise cover among them (籲 灩 灪 爩 麤 齾 齉 龘,
# 32 to 48 strokes), unreachable by the engine's own limit, not by pruning.
MAX_STROKES = 30

# Table budget (spec: 筆畫輸入法 table budget sanity note). Expanding every
# prefix of all ~95k CNS code points gives ~16 MB of runtime JSON, far past the
# largest committed cinbase table (ezbig.json, 2.1 MB), so prefix fan-out is
# granted only to the character sets a stroke typist reaches for; every other
# included plane contributes its complete code alone. Tier names are the
# converter's own (CinToJson.getCharSet in cintojson.py), so the two cannot
# disagree about what "common" means.
CLOSURE_TIERS = frozenset({"big5F", "big5LF"})
FULLCODE_TIERS = frozenset({"big5Other", "bopomofo", "cjk", "cjkExtA"})
# Left out entirely: the ultra-rare planes and symbol sets a stroke typist never
# reaches. Named rather than left implicit so a tier the converter adds becomes
# an error instead of a silent omission (see collect_chardefs). "big5S" is listed
# although getCharSet presently answers "big5LF" for its Big5 符號 branch.
EXCLUDED_TIERS = frozenset({"big5S", "cjkExtB", "cjkExtC", "cjkExtD", "cjkExtE",
                            "cjkExtF", "cjkCIibm", "cjkOther", "phrases", "pua"})

# The order cintojson.py merges its charset tiers in (run -> mergeDicts). A key's
# candidate list is sorted by it, so a colliding key leads with common characters.
CHARSET_LADDER = ["big5F", "big5LF", "big5S", "big5Other", "bopomofo", "cjk",
                  "cjkExtA", "cjkExtB", "cjkExtC", "cjkExtD", "cjkExtE", "cjkExtF",
                  "cjkCIibm", "cjkOther", "phrases", "pua"]
TIER_RANK = {tier: rank for rank, tier in enumerate(CHARSET_LADDER)}

DATA_PROVIDER = "數位發展部"
DATASET = "CNS11643中文標準交換碼全字庫(簡稱全字庫)"
DATASET_PARTS = "全字庫屬性資料集對照表與全字庫中文碼對照表"
LICENSE_URL = "https://data.gov.tw/license"
LICENSE_NAME = "政府資料開放授權條款-第1版"
LICENSE_LATIN = "Open Government Data License"
# The attachment heading the licence itself prescribes; quoted by the .cin header
# and by the shipped notice alike.
EXHIBIT_HEADING = "顯名聲明（%s 附件）：" % LICENSE_NAME
NOTICE_SUFFIX = ".LICENSE.txt"

CIN_HEADS = """%gen_inp
%ename CnsStroke
%cname 筆畫
%encoding UTF-8
%selkey 1234567890
"""

KEYNAME_HEAD = "%keyname begin\n"
KEYNAME_TAIL = "%keyname end\n"
CHARDEF_HEAD = "%chardef begin\n"
CHARDEF_TAIL = "%chardef end\n"


def read_rows(path):
    """Yield (cns_code, value) pairs from a CNS TSV, skipping blank/malformed lines."""
    with open(path, "r", encoding="utf-8-sig") as handle:
        for line in handle:
            line = line.rstrip("\r\n")
            if not line.strip():
                continue
            fields = line.split("\t")
            if len(fields) < 2:
                continue
            yield fields[0].strip(), fields[1].strip()


def load_unicode_by_cns_code(mapping_paths):
    """Join key of the generator: CNS字碼 -> set of Unicode code points."""
    codepoints = {}
    for path in mapping_paths:
        for cns_code, value in read_rows(path):
            try:
                codepoint = int(value, 16)
            except ValueError:
                continue
            codepoints.setdefault(cns_code, set()).add(codepoint)
    return codepoints


def load_stroke_sequences(strokes_path):
    """CNS字碼 -> stroke sequence, only the digits 1..5, empty sequences dropped."""
    sequences = {}
    for cns_code, sequence in read_rows(strokes_path):
        if not sequence:
            continue
        if any(digit not in STROKE_KEY_BY_DIGIT for digit in sequence):
            continue
        sequences[cns_code] = sequence
    return sequences


def stroke_key(sequence):
    """CNS digit sequence -> Five-stroke key string."""
    return "".join(STROKE_KEY_BY_DIGIT[digit] for digit in sequence)


def collect_chardefs(strokes_path, mapping_paths):
    """Map every stroke sequence to its characters, expanding prefixes offline.

    cinbase only ever asks ``isInCharDef`` with the exact composition typed, so
    "candidates after every stroke" needs each prefix as its own key (ADR 0002);
    the shared engine keeps its exact-match semantics untouched. Fan-out is
    limited to CLOSURE_TIERS, with FULLCODE_TIERS contributing the complete code
    only -- see the table budget note above.
    """
    codepoints_by_cns = load_unicode_by_cns_code(mapping_paths)
    classifier = load_charset_classifier()
    tier_by_codepoint = {}

    def tier_of(codepoint):
        tier = tier_by_codepoint.get(codepoint)
        if tier is None:
            tier = classifier.getCharSet("", chr(codepoint))
            tier_by_codepoint[codepoint] = tier
        return tier

    chardefs = {}
    for cns_code, sequence in load_stroke_sequences(strokes_path).items():
        if len(sequence) > MAX_STROKES:
            continue
        key = stroke_key(sequence)
        for codepoint in codepoints_by_cns.get(cns_code, ()):
            tier = tier_of(codepoint)
            if tier in CLOSURE_TIERS:
                for length in range(1, len(key) + 1):
                    chardefs.setdefault(key[:length], set()).add(codepoint)
            elif tier in FULLCODE_TIERS:
                chardefs.setdefault(key, set()).add(codepoint)
    unknown = {tier for tier in tier_by_codepoint.values()
               if tier not in CLOSURE_TIERS | FULLCODE_TIERS | EXCLUDED_TIERS}
    if unknown:
        raise ValueError("cintojson.py gained a charset tier this generator does "
                         "not classify: %s" % ", ".join(sorted(unknown)))
    return chardefs, tier_by_codepoint


def load_charset_classifier():
    """The converter's charset ladder, reused so the two cannot drift apart.

    getCharSet also accumulates each character into that instance's tier dicts and
    counters; the instance here is throwaway, so only the returned tier name is used.
    """
    converter = os.path.join(os.path.dirname(os.path.abspath(__file__)), "cintojson.py")
    spec = importlib.util.spec_from_file_location("cintojson_for_stroke_table", converter)
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module.CinToJson()


def render_cin(chardefs, tier_by_codepoint):
    """Render the CMIME table text: heads, keyname block, then the chardef block.

    Candidates inside a key follow the converter's charset ladder -- common
    planes first, code point order inside a tier -- which is what keeps a
    colliding key such as a single 橫 (thousands of characters) usable.
    """
    out = [CIN_HEADS, KEYNAME_HEAD]
    for key in ROOT_GLYPH_BY_KEY:  # source order is the Five-stroke order h s p n z
        out.append("%s %s\n" % (key, ROOT_GLYPH_BY_KEY[key]))
    out.append(KEYNAME_TAIL)
    out.append(CHARDEF_HEAD)
    for key in sorted(chardefs):
        candidates = sorted(chardefs[key],
                            key=lambda cp: (TIER_RANK[tier_by_codepoint[cp]], cp))
        for codepoint in candidates:
            out.append("%s %s\n" % (key, chr(codepoint)))
    out.append(CHARDEF_TAIL)
    return "".join(out)


def release_year(release):
    """The publication year the exhibit quotes: the release version's leading year."""
    return release[:4] if release[:4].isdigit() else release


def reproduce_commands(release):
    """The commands that regenerate the committed Stroke artifacts.

    One source for the recipe the ``.cin`` header records and the shipped notice
    repeats: the CNS raw inputs live off-repository, so that recipe is all a
    reader has to go on, and the two copies must not be free to drift.
    """
    return [
        "python cnsstroke2cin.py CNS_strokes_sequence.txt <MapingTables 目錄> \\",
        "    -o ../cin/CnsStroke.cin --release %s" % release,
        "python cintojson.py CnsStroke.cin",
    ]


def attribution_exhibit(release):
    """The three 顯名聲明 lines 政府資料開放授權條款-第1版 requires, verbatim.

    Clause 3.2 voids the licence ab initio when the exhibit is missing, so these
    lines exist exactly once, here.  Both carriers render them from this function
    with the same arguments: the ``.cin`` header, where they must stay ``#``
    comments because that is all the converter tolerates above ``%gen_inp``, and
    the notice that ships beside the runtime JSON, which keeps them byte-for-byte
    what the source it documents says.
    """
    return [
        "# 1. %s %s %s %s 版本 %s" % (DATA_PROVIDER, release_year(release),
                                      DATASET, DATASET_PARTS, release),
        "# 2. 此開放資料依政府資料開放授權條款 (%s) 進行公眾釋出，"
        "使用者於遵守本條款各項規定之前提下，得利用之。" % LICENSE_LATIN,
        "# 3. 政府資料開放授權條款：%s" % LICENSE_URL,
    ]


def attribution_header(release):
    """Provenance comments, ending with the OGDL-1.0 顯名聲明 verbatim.

    The exhibit itself is attribution_exhibit()'s; nothing here retypes it.
    """
    lines = [
        "# 文件名稱：CnsStroke.cin —— 筆畫輸入法（五筆畫 h s p n z）碼表",
        "# 產生方式（勿手改此檔）：",
    ]
    lines.extend("#   " + command for command in reproduce_commands(release))
    lines.extend([
        "# 資料來源：CNS_strokes_sequence.txt 之筆順（1 橫 2 豎 3 撇 4 點 5 折），",
        "#           經 CNS2UNICODE_Unicode*.txt 對映至 Unicode 碼位",
        "# 收錄範圍：Big5 常用／次常用字展開全部前綴；其他收錄字級僅收完整筆順；",
        "#           超過 %d 畫者、CJK Ext-B 以後字面及私用區字一概不收" % MAX_STROKES,
        "#",
        "# " + EXHIBIT_HEADING,
    ])
    lines.extend(attribution_exhibit(release))
    lines.append("")
    return "".join(line + "\n" for line in lines)


def generate_cin(strokes_path, mapping_paths, release):
    """CNS open-data files in, the Stroke table .cin text out.

    ``release`` is the open-data version string (release.txt); the attribution
    exhibit that the data license requires quotes it, so it is not optional.
    """
    chardefs, tier_by_codepoint = collect_chardefs(strokes_path, mapping_paths)
    if not chardefs:
        raise ValueError("no stroke code survived the join; check the input files")
    return attribution_header(release) + render_cin(chardefs, tier_by_codepoint)


def license_notice(release):
    """The notice that ships beside the runtime JSON: ``json/<stem>.LICENSE.txt``.

    Users receive ``json/`` and nothing else — the installer excludes ``cin/`` and
    the converter's ``saveList`` has no licence key — so the exhibit has to reach
    them as a file of its own.  The wording comes from attribution_exhibit(), the
    very function that fills the ``.cin`` header, so the two carriers cannot
    disagree about text the licence prescribes.
    """
    lines = [
        "CnsStroke.json 授權聲明 —— 筆畫輸入法（筆畫 碼表）",
        "",
        "本檔隨 CnsStroke.json 一起安裝，是該碼表對其開放資料來源所負的授權聲明。",
        "安裝程式只複製 json/，不含 cin/，而轉換器寫出的 JSON 只有資料欄位，故聲明",
        "以本檔形式送達使用者；聲明文字與 cin/CnsStroke.cin 檔頭由同一函式渲染。",
        "",
        "資料來源：%s %s %s，版本 %s" % (DATA_PROVIDER, DATASET, DATASET_PARTS, release),
        "授權條款：%s（%s），%s" % (LICENSE_NAME, LICENSE_LATIN, LICENSE_URL),
        "",
        "產生方式（勿手改此檔）：",
    ]
    lines.extend(reproduce_commands(release))
    lines.extend([
        "重建本檔不需 CNS 原始資料：上述第一條指令加 --emit-license 即只寫本聲明檔。",
        "",
        "# " + EXHIBIT_HEADING,
    ])
    lines.extend(attribution_exhibit(release))
    return "".join(line + "\n" for line in lines)


def license_path_for(output_path):
    """Where the notice for a generated table ships: the ``cin/`` -> ``json/`` sibling.

    Addressed from the ``-o`` path rather than hardcoded, because the notice
    travels with the runtime JSON the converter writes, not with the source.
    """
    directory, name = os.path.split(output_path)
    stem = name[: -len(".cin")] if name.endswith(".cin") else name
    if os.path.basename(directory) == "cin":
        directory = os.path.join(os.path.dirname(directory), "json")
    return os.path.join(directory, stem + NOTICE_SUFFIX)


def write_license_notice(output_path, release):
    """Write the shipped notice for a generated table; return the path written."""
    notice_path = license_path_for(output_path)
    directory = os.path.dirname(notice_path)
    if directory:
        os.makedirs(directory, exist_ok=True)
    with open(notice_path, "w", encoding="utf-8", newline="\n") as handle:
        handle.write(license_notice(release))
    return notice_path


def resolve_mapping_paths(targets):
    """Accept mapping files and/or a directory holding CNS2UNICODE_Unicode*.txt."""
    paths = []
    for target in targets:
        if os.path.isdir(target):
            paths.extend(sorted(glob.glob(
                os.path.join(target, "CNS2UNICODE_Unicode*.txt"))))
        else:
            paths.append(target)
    return paths


def main(argv=None):
    parser = argparse.ArgumentParser(
        description="Generate the cinbase Stroke table .cin from CNS11643 open data")
    parser.add_argument("strokes", nargs="?",
                        help="CNS_strokes_sequence.txt from Properties.zip "
                             "(not read with --emit-license)")
    parser.add_argument("mapping", nargs="*",
                        help="CNS2UNICODE_Unicode*.txt files, or the directory holding them "
                             "(not read with --emit-license)")
    parser.add_argument("-o", "--output", required=True, help="output .cin path")
    parser.add_argument("--release", required=True,
                        help="open-data release version, e.g. 20260805 (release.txt); "
                             "it is quoted in the attribution exhibit")
    parser.add_argument("--emit-license", action="store_true",
                        help="write only json/<stem>.LICENSE.txt, the notice that ships "
                             "beside the runtime JSON, and exit; the exhibit text comes "
                             "from this file's constants plus --release, so the CNS raw "
                             "inputs are not needed and the committed notice stays "
                             "regenerable without them")
    args = parser.parse_args(argv)

    release = args.release.strip()
    if not release:
        parser.error("--release carries the open-data version from release.txt")

    if args.emit_license:
        print("%s <- 顯名聲明 constants + release %s (no CNS inputs read)" %
              (write_license_notice(args.output, release), release))
        return 0

    if not args.strokes:
        parser.error("strokes is required unless --emit-license is given")
    mapping_paths = resolve_mapping_paths(args.mapping)
    if not mapping_paths:
        parser.error("no CNS2UNICODE_Unicode*.txt mapping file under %s" %
                     ", ".join(args.mapping))

    text = generate_cin(args.strokes, mapping_paths, release=release)
    with open(args.output, "w", encoding="utf-8", newline="\n") as handle:
        handle.write(text)
    print("%s <- %s + %d mapping file(s), release %s" %
          (args.output, os.path.basename(args.strokes), len(mapping_paths), release))
    print("%s <- the same 顯名聲明, for whoever receives the json/ directory" %
          write_license_notice(args.output, release))
    return 0


if __name__ == "__main__":
    sys.exit(main())
